(() => {
'use strict';
if(document.getElementById('inline-rekan-tools-panel'))return;
// R20: panel dengan beberapa pilihan tampilan. Ganti TEMA di bawah: 'terang' | 'esdm' | 'gelap' | 'ubin'.
// Tombol asli tetap dipindahkan apa adanya (event handler, status "Memproses…", tampil/sembunyi per jenis izin tidak berubah).
const TEMA='esdm';
const LOGO_PERISAI='data:image/png;base64,';
const LOGO_PENUH='data:image/png;base64,';
const TOOLS=[
 ['Download Lampiran','lampiran','⬇','Unduh semua lampiran'],
 ['Simpan Lampiran ke Drive','lampiran','☁','Simpan ke Google Drive PATGTL'],
 ['Salin Data Teknis Pemohon','evaluasi','⧉','Salin ke Form Isian Evaluator INLINE ESDM'],
 ['Cek Lokasi Sumur','evaluasi','◎','Wilayah, zona, saran debit & masa'],
 ['Unduh KML Lokasi Proyek','evaluasi','⌖','KML lokasi proyek OSS'],
 ['Data Lengkap Pengusahaan','kirim','↗','Kirim ke Form Evaluator'],
 ['Data Lengkap Persetujuan','kirim','↗','Kirim ke Form Evaluator'],
 ['Data Lengkap Sumur Pantau/Imbuhan','kirim','↗','Kirim ke Form Evaluator'],
 ['Data Lengkap Dewatering','kirim','↗','Kirim ke Form Evaluator'],
 ['Pengembalian','lain','↩','Catat pengembalian berkas'],
 ['Impor Data Wilayah','lain','⇪','Perbarui data wilayah di PC ini']
];
const GROUPS=[['evaluasi','Evaluasi'],['lampiran','Lampiran'],['kirim','Kirim data'],['lain','Lainnya']];
const byLabel=new Map(TOOLS.map((t,i)=>[t[0],{group:t[1],icon:t[2],hint:t[3],order:i}]));
const key='inline-rekan-panel-collapsed';
let collapsed=true;try{const v=sessionStorage.getItem(key);if(v!==null)collapsed=v==='1';}catch{}
const P='#inline-rekan-tools-panel';
const css=`
${P}{--bg:#fff;--line:#e4e7ec;--head:#fff;--headText:#101828;--sub:#667085;--card:#fff;--cardText:#1d2939;--cardLine:#eaecf0;--hint:#667085;--label:#98a2b3;--primary:#1f6f43;--primaryText:#fff;--primaryHover:#18593a;--foot:#f9fafb;
 position:fixed;right:20px;bottom:20px;z-index:99999;width:304px;max-width:calc(100vw - 40px);background:var(--bg);border:1px solid var(--line);border-radius:16px;box-shadow:0 12px 36px rgba(16,24,40,.22);overflow:hidden;font:14px/1.4 "Segoe UI",Arial,sans-serif!important;color:var(--cardText)}
${P} *{box-sizing:border-box;font-family:"Segoe UI",Arial,sans-serif!important;letter-spacing:normal!important;text-transform:none!important}
${P} .irp-head{all:unset;display:flex;align-items:center;gap:10px;width:100%;padding:12px 14px;cursor:pointer;background:var(--head);border-bottom:1px solid var(--line);box-sizing:border-box}
${P} .irp-logo{height:38px;width:auto;flex:none;object-fit:contain;display:block}
${P} .irp-name{border-left:1px solid rgba(17,17,17,.22);padding-left:10px;min-width:0}
${P} .irp-title{font-weight:800;font-size:16px;color:var(--headText);letter-spacing:.02em!important}
${P} .irp-sub{font-size:11px;line-height:1.3;color:var(--sub)}
${P} .irp-chev{margin-left:auto;color:var(--sub);font-size:12px;transition:transform .15s}
${P}.irp-collapsed{width:auto;border-radius:999px}
${P}.irp-collapsed .irp-head{padding:7px 18px 7px 14px;border-bottom:0}
${P} .irp-shield{display:none;height:36px;width:auto;flex:none;transition:transform .3s cubic-bezier(.2,.9,.3,1.4)}
${P}.irp-collapsed .irp-logo,${P}.irp-collapsed .irp-name{display:none}
${P}.irp-collapsed .irp-shield{display:block}
${P}.irp-collapsed .irp-head{padding:7px 14px 7px 10px;gap:8px}
${P} .irp-head:hover .irp-shield{transform:scale(1.06)}
${P}.irp-collapsed .irp-sub,${P}.irp-collapsed .irp-body,${P}.irp-collapsed .irp-foot{display:none}
${P}.irp-collapsed .irp-chev{transform:rotate(180deg)}
${P} .irp-body{max-height:calc(100vh - 190px);overflow:auto;padding:6px 12px 12px}
${P} .irp-group{margin-top:8px}
${P} .irp-group:not(:has(button[data-irp]:not([style*="display: none"]))){display:none}
${P} .irp-label{font-size:11px;font-weight:700;color:var(--label);text-transform:uppercase!important;letter-spacing:.07em!important;margin:4px 4px 6px}
${P} .irp-list{display:flex;flex-direction:column;gap:6px}
${P} button[data-irp]{all:unset;box-sizing:border-box;display:grid;grid-template-columns:32px 1fr;grid-template-rows:auto auto;column-gap:10px;align-items:center;width:100%;padding:8px 10px!important;border-radius:10px!important;border:1px solid var(--cardLine)!important;background:var(--card)!important;color:var(--cardText)!important;font:600 13.5px/1.25 "Segoe UI",Arial,sans-serif!important;text-align:left!important;cursor:pointer;transition:background .12s,border-color .12s,transform .08s;position:static!important;margin:0!important;box-shadow:none!important}
${P} button[data-irp]::before{content:attr(data-icon);grid-row:1/3;width:32px;height:32px;border-radius:8px;display:grid;place-items:center;font-size:16px;font-weight:700;background:var(--soft);color:var(--main)}
${P} button[data-irp]::after{content:attr(data-hint);grid-column:2;font-weight:400;font-size:11.5px;color:var(--hint)}
${P} button[data-irp]:hover{background:var(--soft)!important;border-color:var(--edge)!important}
${P} button[data-irp]:active{transform:scale(.98)}
${P} button[data-irp]:focus-visible{outline:2px solid var(--main)!important;outline-offset:2px}
${P} button[data-irp]:disabled{cursor:progress;opacity:.7}
${P} button[data-irp]:disabled::before{content:"…"}
${P} button[data-irp="Simpan Lampiran ke Drive"]::before{content:""!important;background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cg%20fill%3D%22%23111%22%20stroke%3D%22%23f5e62a%22%20stroke-width%3D%22.9%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M8%203h8l7.5%2013h-7.7z%22/%3E%3Cpath%20d%3D%22M8%203l4%206.6-7.7%2012.9-3.8-6.5z%22/%3E%3Cpath%20d%3D%22M8.2%2016h15.3l-3.8%206.5H4.3z%22/%3E%3C/g%3E%3C/svg%3E")!important;background-repeat:no-repeat!important;background-position:center!important;background-size:20px 20px!important}
${P} button[data-irp="Simpan Lampiran ke Drive"]:disabled::before{content:"…"!important;background-image:none!important}
${P} button[data-group=kirim]{--main:#1f6f43;--soft:#ecfdf3;--edge:#abefc6}
${P} button.irp-primary{background:var(--primary)!important;border-color:var(--primary)!important;color:var(--primaryText)!important}
${P} button.irp-primary::before{background:rgba(255,255,255,.2);color:var(--primaryText)}
${P} button.irp-primary::after{color:var(--primaryText);opacity:.8}
${P} button.irp-primary:hover{background:var(--primaryHover)!important;border-color:var(--primaryHover)!important}
${P} button[data-group=evaluasi]{--main:#b54708;--soft:#fffaeb;--edge:#fedf89}
${P} button[data-group=lampiran]{--main:#175cd3;--soft:#eff8ff;--edge:#b2ddff}
${P} button[data-group=lain]{--main:#475467;--soft:#f2f4f7;--edge:#d0d5dd}
${P} button[data-irp="Pengembalian"]{--main:#b42318;--soft:#fef3f2;--edge:#fecdca}
${P} .irp-help{all:unset;box-sizing:border-box;width:24px;height:24px;border-radius:50%!important;background:#111!important;color:#f5e62a!important;display:grid;place-items:center;font-size:13px!important;font-weight:800!important;cursor:pointer;flex:none;transition:transform .2s cubic-bezier(.2,.9,.3,1.4),background .15s}
${P} .irp-help:hover{transform:scale(1.12)}
${P} .irp-help:active{transform:scale(.95)}
${P} .irp-help:focus-visible{outline:2px solid #111!important;outline-offset:2px}
${P} details{margin-top:12px;border:1px solid #fedf89;background:#fffcf5;border-radius:10px;padding:8px 10px;font-size:12px;color:#7a5a12}
${P} summary{cursor:pointer;font-weight:700;color:#93370d}
${P} details p{margin:6px 0 0}
${P} .irp-foot{display:flex;align-items:center;gap:8px;padding:8px 14px;border-top:1px solid var(--line);background:var(--foot);font-size:11px;color:var(--sub)}
${P} .irp-foot img{height:24px;width:auto;display:block}
${P} .irp-foot span{margin-left:auto;font-weight:600}
/* ===== Tema ESDM: kuning-hitam ===== */
${P}.t-esdm{--head:#f5e62a;--headText:#111;--sub:#3d3a12;--line:#eee7a0;--primary:#111;--primaryText:#f5e62a;--primaryHover:#2b2b2b;--foot:#fffbd1;border:1px solid rgba(17,17,17,.25)}
${P}.t-esdm .irp-head{border-bottom:1px solid rgba(17,17,17,.12)}
${P}.t-esdm .irp-label{color:#6b6413}
${P}.t-esdm button[data-irp]{--main:#111!important;--soft:#fffbd1!important;--edge:#e3d64a!important}
${P}.t-esdm button[data-irp]::before{background:#f5e62a;color:#111}
${P}.t-esdm button.irp-primary::before{background:#f5e62a;color:#111}
${P}.t-esdm .irp-foot{border-top:1px solid #eee7a0}
/* ===== Tema gelap ===== */
${P}.t-gelap{--bg:#111827;--line:#1f2937;--head:#0b1220;--headText:#f9fafb;--sub:#9ca3af;--card:#1f2937;--cardText:#f3f4f6;--cardLine:#273244;--hint:#9ca3af;--label:#6b7280;--primary:#f5e62a;--primaryText:#111;--primaryHover:#ffe94d;--foot:#0b1220}
${P}.t-gelap button[data-irp]{--soft:#273244!important;--edge:#374151!important}
${P}.t-gelap button[data-group=kirim]{--main:#86efac}${P}.t-gelap button[data-group=evaluasi]{--main:#fbbf24}${P}.t-gelap button[data-group=lampiran]{--main:#93c5fd}${P}.t-gelap button[data-group=lain]{--main:#d1d5db}${P}.t-gelap button[data-irp="Pengembalian"]{--main:#fca5a5}
${P}.t-gelap button[data-irp]::before{background:#111827}
${P}.t-gelap button.irp-primary::before{background:rgba(0,0,0,.12);color:#111}
${P}.t-gelap details{background:#1f2937;border-color:#374151;color:#d1d5db}${P}.t-gelap summary{color:#fbbf24}
${P}.t-gelap .irp-foot img{background:#fff;border-radius:6px;padding:2px 6px;height:26px}
/* ===== Tema ubin: kisi 2 kolom ===== */
${P}.t-ubin{width:336px}
${P}.t-ubin.irp-collapsed{width:auto}
${P}.t-ubin .irp-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}
${P}.t-ubin button[data-irp]{grid-template-columns:1fr;grid-template-rows:auto auto;justify-items:center;text-align:center!important;padding:12px 8px 10px!important;row-gap:6px;font-size:12.5px!important;min-height:92px}
${P}.t-ubin button[data-irp]::before{grid-row:auto;width:38px;height:38px;border-radius:12px;font-size:18px}
${P}.t-ubin button[data-irp]::after{display:none}
${P}.t-ubin button[data-irp]{order:var(--o)}
/* ===== Gerak halus ===== */
${P}{transform-origin:bottom right}
${P}.irp-anim{animation:irp-pop .24s cubic-bezier(.2,.9,.3,1.2)}
@keyframes irp-pop{from{transform:scale(.94);opacity:.4}to{transform:scale(1);opacity:1}}
${P} .irp-body{animation:irp-fade .22s ease-out}
@keyframes irp-fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
${P} button[data-irp]{position:relative!important;overflow:hidden;transition:background .18s ease,border-color .18s ease,transform .16s cubic-bezier(.2,.9,.3,1.3),box-shadow .18s ease!important}
${P} button[data-irp]:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(17,17,17,.10)!important}
${P} button[data-irp]:active{transform:translateY(0) scale(.97);box-shadow:0 1px 3px rgba(17,17,17,.10)!important;transition-duration:.08s!important}
${P} button[data-irp]::before{transition:transform .2s cubic-bezier(.2,.9,.3,1.4)}
${P} button[data-irp]:hover::before{transform:scale(1.08) rotate(-4deg)}
${P} button[data-irp]:disabled::before{animation:irp-pulse 1s ease-in-out infinite}
@keyframes irp-pulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(.9);opacity:.55}}
${P} .irp-ripple{position:absolute;border-radius:50%;pointer-events:none;background:rgba(245,230,42,.55);transform:scale(0);animation:irp-ripple .55s ease-out forwards}
@keyframes irp-ripple{to{transform:scale(1);opacity:0}}
${P} .irp-head{transition:background .18s ease}
${P} .irp-chev{transition:transform .25s cubic-bezier(.2,.9,.3,1.2)!important}
${P} .irp-logo{transition:transform .3s cubic-bezier(.2,.9,.3,1.4)}
${P} .irp-head:hover .irp-logo{transform:scale(1.05)}
${P} details[open] p{animation:irp-fade .2s ease-out}
@media (prefers-reduced-motion:reduce){${P},${P} *{animation:none!important;transition:none!important}}
`
const style=document.createElement('style');style.id='inline-rekan-tools-style';style.textContent=css;document.head.append(style);
const panel=document.createElement('section');panel.id='inline-rekan-tools-panel';panel.className='t-'+TEMA;panel.setAttribute('aria-label','AIRA');
const head=document.createElement('button');head.type='button';head.className='irp-head';head.setAttribute('aria-controls','inline-rekan-tools-body');
head.innerHTML='<img class="irp-logo" alt="Kementerian ESDM" src="'+LOGO_PENUH+'"><img class="irp-shield" alt="AIRA — Kementerian ESDM" src="'+LOGO_PERISAI+'"><span class="irp-name"><div class="irp-title">AIRA</div><div class="irp-sub">Alat Bantu Verifikasi dan Evaluasi Perizinan Air Tanah</div></span><span class="irp-chev" aria-hidden="true">▼</span>';
const body=document.createElement('div');body.className='irp-body';body.id='inline-rekan-tools-body';
const lists={};
for(const [id,title] of GROUPS){const g=document.createElement('div');g.className='irp-group';g.innerHTML='<div class="irp-label">'+title+'</div>';const l=document.createElement('div');l.className='irp-list';g.append(l);body.append(g);lists[id]=l;}
const tip=document.createElement('details');
tip.innerHTML='<summary>Tips penulisan akuifer</summary><p>Di INLINE gunakan <b>#lt#</b> untuk &lt;, <b>#gt#</b> untuk &gt;, <b>#le#</b> untuk ≤, <b>#ge#</b> untuk ≥. Contoh: <b>#lt# 40</b> atau <b>#gt# 60</b>.</p><p>Pastikan <b>preview PDF produk izin berhasil</b> sebelum mengirim permohonan.</p>';
body.append(tip);
// ===== Petunjuk penggunaan (2.11) =====
const PETUNJUK=[
 ['Evaluasi',[
  ['Salin Data Teknis Pemohon','⧉','Menyalin data teknis yang diisi pemohon ke Form Isian Evaluator INLINE ESDM.',['Daftar kolom yang akan disalin sebelum diproses','Perbandingan bila isian evaluator sudah berbeda: nilai lama dicoret, nilai pemohon hijau','Pilihan <b>Salin yang kosong saja</b> atau <b>Timpa dengan data pemohon</b>']],
  ['Cek Lokasi Sumur','◎','Memeriksa lokasi setiap sumur dan memberi saran evaluasi.',['Posisi sumur terhadap lokasi proyek OSS','Desa, kecamatan, kabupaten/kota, provinsi','CAT, zona konservasi, dan debit optimum','Kawasan industri, zona bebas air tanah, skala usaha dari database izin','Saran debit dan masa berlaku, lalu tombol <b>Isi Otomatis</b> (Debit Hasil Evaluasi, Volume Harian, masa berlaku, skala, alamat) — semua nilai bisa diedit dulu'],'Perlu Data Wilayah diimpor sekali di PC ini. Hasil cek adalah saran, tetap diperiksa.'],
  ['Unduh KML Lokasi Proyek','⌖','Mengunduh file KML lokasi proyek dari OSS untuk dibuka di Google Earth atau aplikasi GIS.',['File .kml lokasi proyek tersimpan di folder unduhan']]
 ]],
 ['Lampiran',[
  ['Download Lampiran','⬇','Mengunduh semua PDF lampiran permohonan sekaligus ke satu folder di PC.',['Progres unduhan pada tombol (Download 3/12)','Nama file berurutan seperti di INLINE: 01 - …, 02 - …']],
  ['Simpan Lampiran ke Drive','☁','Menyimpan semua lampiran ke Google Drive PATGTL (folder provinsi) dengan akun Google masing-masing.',['Jendela kecil Google sebentar; pertama kali, pilih akun Drive Anda (diingat)','Daftar PDF yang dicentang satu per satu dan bilah progres','Hasil: akun upload, folder, dan tautan <b>Buka folder di Google Drive</b>'],'Izinkan pop-up untuk ngantor.esdm.go.id. Ganti akun: ikon Tampermonkey → Ganti akun Google Drive (AIRA).']
 ]],
 ['Kirim data',[
  
  ['Data Lengkap (Pengusahaan / Persetujuan / Dewatering / Sumur Pantau/Imbuhan)','↗','Mengirim data permohonan ke Form Data Evaluator (Sheets bersama). Tombol hanya muncul sesuai jenis izin.',['Pop up <b>nomor baris + catatan</b>: baris kosong, baris permohonan ini (revisi), atau dipakai permohonan lain (diblokir)','Saat revisi: catatan terakhir dan catatan otomatis terbaru, dengan tombol <b>Perbarui</b> dan <b>Kembalikan catatan terakhir</b>','Ringkasan data untuk dicek sebelum dikirim'],'Sumur Imbuhan: catatan bawaan “Sesuai”, tanggal evaluasi terisi otomatis.']
 ]],
 ['Lainnya',[
  ['Pengembalian','↩','Mencatat pengembalian berkas beserta catatan pengembaliannya ke rekap.',['Konfirmasi data yang akan dicatat','Hasil dengan nama lengkap evaluator dan waktu catatan']],
  ['Impor Data Wilayah','⇪','Memasang atau memperbarui data wilayah (administrasi, CAT, zona) di PC ini.',['Cukup sekali per PC; ulangi bila ada pembaruan data wilayah']]
 ]]
];
const PS='#aira-petunjuk';
const pcss=`
${PS}{width:min(560px,94vw);max-height:86vh;padding:0;border:0;border-radius:16px;box-shadow:0 24px 64px rgba(16,24,40,.35);overflow:hidden;color:#1d2939;background:#fff;font:14px/1.5 "Segoe UI",Arial,sans-serif}
${PS}[open]{display:flex;flex-direction:column;animation:aira-pj-pop .28s cubic-bezier(.2,.9,.3,1.2)}
${PS}::backdrop{background:rgba(16,24,40,.45);animation:aira-pj-fade .2s ease}
${PS} *{box-sizing:border-box;font-family:"Segoe UI",Arial,sans-serif!important;letter-spacing:normal!important;text-transform:none!important}
${PS} .pj-head{display:flex;align-items:center;gap:12px;padding:16px 20px;background:#f5e62a;border-bottom:1px solid rgba(17,17,17,.12)}
${PS} .pj-head h2{margin:0;font-size:17px!important;font-weight:700!important;color:#111!important;flex:1}
${PS} .pj-head small{display:block;font-size:11px!important;font-weight:700!important;letter-spacing:.08em!important;color:#6b6413!important}
${PS} .pj-x{all:unset;cursor:pointer;width:32px;height:32px;border-radius:8px;display:grid;place-items:center;font-size:18px;color:#111;transition:background .15s}
${PS} .pj-x:hover{background:rgba(0,0,0,.08)}
${PS} .pj-body{overflow:auto;padding:14px 20px 18px}
${PS} .pj-intro{margin:0 0 10px;font-size:13px;color:#475467}
${PS} .pj-grp{margin:14px 0 6px;font-size:11px!important;font-weight:800!important;letter-spacing:.1em!important;color:#6b6413!important;text-transform:uppercase!important}
${PS} details{border:1px solid #eaecf0;border-radius:12px;margin:6px 0;background:#fff;transition:border-color .15s,background .15s}
${PS} details[open]{border-color:#eee7a0;background:#fffdf0}
${PS} summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:30px 1fr 16px;gap:10px;align-items:center;padding:10px 12px}
${PS} summary::-webkit-details-marker{display:none}
${PS} summary i{font-style:normal;width:30px;height:30px;border-radius:8px;background:#f5e62a;display:grid;place-items:center;font-weight:700;color:#111}
${PS} summary b{display:block;font-size:13.5px;color:#101828}
${PS} summary span{display:block;font-size:12px;color:#667085;line-height:1.4}
${PS} summary em{font-style:normal;color:#98a2b3;transition:transform .2s}
${PS} details[open] summary em{transform:rotate(90deg)}
${PS} .pj-in{padding:0 14px 12px 52px;font-size:12.5px;color:#344054;animation:aira-pj-fade .2s ease}
${PS} .pj-in ul{margin:4px 0 0;padding-left:18px}${PS} .pj-in li{margin:3px 0}
${PS} .pj-in .pj-note{margin:8px 0 0;padding:7px 10px;border-radius:8px;background:#fffaeb;color:#93370d;font-size:12px}
${PS} .pj-foot{padding:12px 20px;border-top:1px solid #eaecf0;font-size:12px;color:#667085;background:#fcfcfd}
@keyframes aira-pj-pop{from{opacity:0;transform:translateY(10px) scale(.97)}to{opacity:1;transform:none}}
@keyframes aira-pj-fade{from{opacity:0}to{opacity:1}}
@media (prefers-reduced-motion:reduce){${PS},${PS} *,${PS}::backdrop{animation:none!important;transition:none!important}}
`;
const pst=document.createElement('style');pst.textContent=pcss;document.head.append(pst);
function bukaPetunjuk(){
 document.getElementById('aira-petunjuk')?.remove();
 const d=document.createElement('dialog');d.id='aira-petunjuk';d.setAttribute('aria-label','Petunjuk AIRA');
 let h='<div class="pj-head"><div style="flex:1"><small>AIRA · PETUNJUK</small><h2>Fungsi setiap tombol</h2></div><button type="button" class="pj-x" aria-label="Tutup">✕</button></div><div class="pj-body"><p class="pj-intro">Klik nama tombol untuk melihat apa yang ditampilkan. Tombol di panel muncul sesuai halaman dan jenis izin yang sedang dibuka.</p>';
 for(const [grp,items] of PETUNJUK){h+='<div class="pj-grp">'+grp+'</div>';for(const [nama,ikon,fungsi,tampil,catatan] of items){h+='<details><summary><i aria-hidden="true">'+ikon+'</i><div><b>'+nama+'</b><span>'+fungsi+'</span></div><em aria-hidden="true">›</em></summary><div class="pj-in">Yang ditampilkan:<ul>'+tampil.map(t=>'<li>'+t+'</li>').join('')+'</ul>'+(catatan?'<div class="pj-note">'+catatan+'</div>':'')+'</div></details>';}}
 h+='</div><div class="pj-foot">Token evaluator: ikon Tampermonkey → <b>Pengaturan INLINE</b>. Kendala? Hubungi pengelola AIRA di BKAT.</div>';
 d.innerHTML=h;document.body.append(d);
 const tutup=()=>{d.close();d.remove();};
 d.querySelector('.pj-x').onclick=tutup;d.addEventListener('close',()=>d.remove());
 d.addEventListener('click',e=>{if(e.target===d)tutup();});
 d.showModal();
}
const help=document.createElement('button');help.type='button';help.className='irp-help';help.textContent='?';help.title='Petunjuk: fungsi setiap tombol';help.setAttribute('aria-label','Petunjuk: fungsi setiap tombol');help.onclick=bukaPetunjuk;

const foot=document.createElement('div');foot.className='irp-foot';foot.innerHTML='<span>© BKAT 2026</span>';
foot.prepend(help);
panel.append(head,body,foot);document.body.append(panel);
function render(animate){panel.classList.toggle('irp-collapsed',collapsed);if(animate){panel.classList.remove('irp-anim');void panel.offsetWidth;panel.classList.add('irp-anim');}head.setAttribute('aria-expanded',String(!collapsed));head.title=collapsed?'Tampilkan AIRA':'Sembunyikan';}
head.onclick=()=>{collapsed=!collapsed;render(true);try{sessionStorage.setItem(key,collapsed?'1':'0');}catch{}};
render();
function adopt(){
 for(const button of document.querySelectorAll('button')){
  if(panel.contains(button))continue;
  const label=button.textContent.trim(),t=byLabel.get(label);
  if(!t||button.style.position!=='fixed')continue;
  button.style.position='static';button.style.removeProperty('right');button.style.removeProperty('bottom');button.style.removeProperty('z-index');
  button.type='button';button.dataset.irp=label;button.dataset.group=t.group;button.dataset.icon=t.icon;button.dataset.hint=t.hint;button.style.order=String(t.order);
  lists[t.group].append(button);
 }
}
// Efek riak (ripple) saat tombol ditekan. Elemen riak tidak berisi teks, jadi label tombol tidak berubah.
panel.addEventListener('pointerdown',e=>{
 const b=e.target.closest('button[data-irp]');if(!b||b.disabled||!panel.contains(b))return;
 try{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;}catch{}
 const r=b.getBoundingClientRect(),size=Math.max(r.width,r.height)*2.2,s=document.createElement('span');
 s.className='irp-ripple';s.setAttribute('aria-hidden','true');
 s.style.cssText='width:'+size+'px;height:'+size+'px;left:'+(e.clientX-r.left-size/2)+'px;top:'+(e.clientY-r.top-size/2)+'px';
 b.append(s);setTimeout(()=>s.remove(),600);
});
adopt();
new MutationObserver(adopt).observe(document.body,{childList:true,subtree:true});
})();
